import sys, re
S, H = sys.argv[1], sys.argv[2]
def patch(path, reps, first_only=False):
    s = open(path, encoding='utf-8').read()
    for a, b in reps:
        assert a in s, (path, a[:80])
        s = s.replace(a, b, 1) if first_only else s.replace(a, b)
    open(path, 'w', encoding='utf-8').write(s); print('patched', path.split('/')[-1], len(reps))
